import collections
def clas(f):
    c = f.center(); r = math.hypot(c.X, c.Y)
    if isinstance(f.geom_type, str): gt = f.geom_type
    else: gt = str(f.geom_type)
    return gt, round(c.Z,4), round(r,4)
